9	import { MobileNav } from "./mobile-nav";
10	import type { NavItem } from "@/types/navigation";
11	
12	function NavDropdown({ item }: { item: NavItem }) {
13	  return (
14	    <div className="group relative">
15	      <button className="flex items-center gap-1 text-sm font-medium text-foreground/80 transition-colors hover:text-foreground">
16	        {item.label}
17	        <ChevronDown className="h-3.5 w-3.5 transition-transform group-hover:rotate-180" />
18	      </button>
19	      <div className="invisible absolute left-0 top-full z-50 mt-2 min-w-[200px] rounded-lg border bg-popover p-2 opacity-0 shadow-lg transition-all group-hover:visible group-hover:opacity-100">
20	        {item.children?.map((child) => (
21	          <Link
22	            key={child.href}
23	            href={child.href}
24	            className="flex items-center gap-2 rounded-md px-3 py-2 text-sm transition-colors hover:bg-accent"
25	          >
26	            {child.label}
27	            {child.comingSoon && (
28	              <span className="rounded-full bg-brand-yellow/20 px-2 py-0.5 text-[10px] font-medium text-brand-navy">
29	                Soon
30	              </span>
31	            )}
32	          </Link>
33	        ))}
34	      </div>
35	    </div>
36	  );
37	}
38	
39	export function Navbar() {
40	  const [mobileOpen, setMobileOpen] = useState(false);
41	
42	  return (
43	    <header className="sticky top-0 z-50 w-full border-b bg-background/80 backdrop-blur-lg">
44	      <nav className="mx-auto flex h-16 max-w-7xl items-center justify-between px-4 sm:px-6 lg:px-8">
45	        {/* Logo */}
46	        <Link href="/" className="flex items-center gap-2">
47	          <span className="text-xl font-bold tracking-tight text-brand-navy">
48	            Boldteq
49	          </span>
50	        </Link>
51	
52	        {/* Desktop Nav */}
53	        <div className="hidden items-center gap-6 lg:flex">
54	          {NAV_ITEMS.map((item) =>
55	            item.children ? (
56	              <NavDropdown key={item.label} item={item} />
57	            ) : (
58	              <Link
59	                key={item.href}
60	                href={item.href}
61	                className="text-sm font-medium text-foreground/80 transition-colors hover:text-foreground"
62	              >
63	                {item.label}
64	              </Link>
65	            )
66	          )}
67	        </div>
68	
69	        {/* Desktop CTAs */}
70	        <div className="hidden items-center gap-3 lg:flex">
71	          {CTA_NAV.map((item) =>
72	            item.external ? (
73	              <a
74	                key={item.label}
75	                href={item.href}
76	                target="_blank"
77	                rel="noopener noreferrer"
78	                className="text-sm font-medium text-foreground/80 transition-colors hover:text-foreground"
79	              >
80	                {item.label}
81	              </a>
82	            ) : (
83	              <ButtonLink
84	                key={item.label}
85	                href={item.href}
86	                size="sm"
87	                className="rounded-full border-0 bg-gradient-to-r from-[#21cfff] to-[#019ae6] text-white hover:brightness-110"
88	              >
89	                {item.label}
90	              </ButtonLink>
91	            )
92	          )}
93	        </div>
94	
95	        {/* Mobile Menu Toggle */}
96	        <Button
97	          variant="ghost"
98	          size="icon"
99	          className="lg:hidden"
100	          onClick={() => setMobileOpen(true)}
101	        >
102	          <Menu className="h-5 w-5" />
103	          <span className="sr-only">Open menu</span>
104	        </Button>
105	      </nav>
106	
107	      <MobileNav open={mobileOpen} onClose={() => setMobileOpen(false)} />
108	    </header>
109	  );
110	}
