17	function MobileNavGroup({
18	  item,
19	  onNavigate,
20	}: {
21	  item: NavItem;
22	  onNavigate: () => void;
23	}) {
24	  const [expanded, setExpanded] = useState(false);
25	
26	  if (!item.children) {
27	    return (
28	      <Link
29	        href={item.href}
30	        onClick={onNavigate}
31	        className="block rounded-md px-3 py-2.5 text-base font-medium text-foreground transition-colors hover:bg-accent"
32	      >
33	        {item.label}
34	      </Link>
35	    );
36	  }
37	
38	  return (
39	    <div>
40	      <button
41	        onClick={() => setExpanded(!expanded)}
42	        className="flex w-full items-center justify-between rounded-md px-3 py-2.5 text-base font-medium text-foreground transition-colors hover:bg-accent"
43	      >
44	        {item.label}
45	        <ChevronDown
46	          className={`h-4 w-4 transition-transform ${expanded ? "rotate-180" : ""}`}
47	        />
48	      </button>
49	      {expanded && (
50	        <div className="ml-4 space-y-1 border-l pl-3">
51	          {item.children.map((child) => (
52	            <Link
53	              key={child.href}
54	              href={child.href}
55	              onClick={onNavigate}
56	              className="flex items-center gap-2 rounded-md px-3 py-2 text-sm text-muted-foreground transition-colors hover:text-foreground"
57	            >
58	              {child.label}
59	              {child.comingSoon && (
60	                <span className="rounded-full bg-brand-yellow/20 px-2 py-0.5 text-[10px] font-medium text-brand-navy">
61	                  Soon
62	                </span>
63	              )}
64	            </Link>
65	          ))}
66	        </div>
67	      )}
68	    </div>
69	  );
70	}
71	
72	export function MobileNav({
73	  open,
74	  onClose,
75	}: {
76	  open: boolean;
77	  onClose: () => void;
78	}) {
79	  return (
80	    <Sheet open={open} onOpenChange={onClose}>
81	      <SheetContent side="right" className="w-[300px] p-0">
82	        <SheetHeader className="border-b px-4 py-4">
83	          <div className="flex items-center justify-between">
84	            <SheetTitle className="text-lg font-bold text-brand-navy">
85	              Boldteq
86	            </SheetTitle>
87	            <Button variant="ghost" size="icon-sm" onClick={onClose}>
88	              <X className="h-4 w-4" />
89	              <span className="sr-only">Close menu</span>
90	            </Button>
91	          </div>
92	        </SheetHeader>
93	
94	        <div className="flex flex-col gap-1 px-2 py-4">
95	          {NAV_ITEMS.map((item) => (
96	            <MobileNavGroup
97	              key={item.label}
98	              item={item}
99	              onNavigate={onClose}
100	            />
101	          ))}
102	        </div>
103	
104	        <div className="mt-auto space-y-3 border-t px-4 py-4">
105	          {CTA_NAV.map((item) =>
106	            item.external ? (
107	              <a
108	                key={item.label}
109	                href={item.href}
110	                target="_blank"
111	                rel="noopener noreferrer"
112	                onClick={onClose}
113	                className="block text-center text-sm font-medium text-muted-foreground transition-colors hover:text-foreground"
114	              >
115	                {item.label}
116	              </a>
117	            ) : (
118	              <ButtonLink
119	                key={item.label}
120	                href={item.href}
121	                className="w-full justify-center rounded-full border-0 bg-gradient-to-r from-[#21cfff] to-[#019ae6] text-white"
122	              >
123	                {item.label}
124	              </ButtonLink>
125	            )
126	          )}
127	        </div>
128	      </SheetContent>
129	    </Sheet>
